import React, { useState } from 'react';
import EmployeeService from '../Services/EmployeeService';
import '../App.css';

const LoginComponent = ({ onLogin }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');

    const handleLogin = (e) => {
        e.preventDefault();
        EmployeeService.login(username, password)
            .then((response) => {
                onLogin(response.data);
            })
            .catch((err) => {
                setError('Invalid Username or Password');
            });
    };

    return (
        <div className="login-container">
            <div className="login-card">
                <h2 className="text-center bw-title">EMS Login</h2>
                <form onSubmit={handleLogin}>
                    <div className="form-group mb-3">
                        <label className="bw-label">Username</label>
                        <input
                            type="text"
                            className="form-control bw-input"
                            value={username}
                            onChange={(e) => setUsername(e.target.value)}
                            placeholder="Enter username"
                            required
                        />
                    </div>
                    <div className="form-group mb-3">
                        <label className="bw-label">Password</label>
                        <input
                            type="password"
                            className="form-control bw-input"
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="Enter password"
                            required
                        />
                    </div>
                    {error && <div className="alert alert-danger bw-alert">{error}</div>}
                    <button type="submit" className="btn btn-dark w-100 bw-btn">Login</button>
                </form>
                <div className="mt-3 text-center">
                    <small>
                        Admin: admin / admin123 <br/>
                        Employee: [any username] / employee@1
                    </small>
                </div>
            </div>
        </div>
    );
};

export default LoginComponent;
